  rAnchor: { x: 390, y: 121.984 },
  pT: [0, 0.43, 0.65, 1.0]
};

var currentStep = 0;
var drag = null;

var defs = draw.defs();
var arrowMarker = draw.marker(12, 8, function (add) {
  add.path('M0,0 L12,4 L0,8 Z').fill(black);
});
