}

infArrow = guideLayer.line(0, 0, 1, 1).stroke({ color: black, width: 2.4, linecap: 'round' });
infArrow.marker('end', arrowMarker);

function makePoint(kind, idx) {
  var c = pointLayer.circle(20).fill(black).center(0, 0);
  c.css('cursor', 'pointer');
  c.on('mousemove', function (e) {
    var name = kind + (idx + 1);
    showTooltip(name + ': drag along its magenta line to change the corresponding projection ray.', e);
  });
  c.on('mouseleave', function () { hideTooltip(); });
  c.on('click', function () {
