    family: 'Times New Roman, Georgia, serif',
    size: 34,
    weight: '700'
  }).fill('#111').attr({
    'paint-order': 'stroke',
    stroke: '#fff',
    'stroke-width': 4,
    'stroke-linejoin': 'round'
  });
}

for (var k = 0; k < 4; k++) {
  pLabels[k] = makeLabel('P' + sub(k + 1));
  qLabels[k] = makeLabel('Q' + sub(k + 1));
  if (k > 0) rLabels[k] = makeLabel('R' + sub(k + 1));
}
