infLabel = makeLabel('R' + sub(1) + ' → ∞').font({ size: 36 });

formulaText = panelLayer.text('CR(A₁,A₂,A₃,A₄) = (A₁A₃/A₂A₃) / (A₁A₄/A₂A₄)')
