var panelBg = panelLayer.rect(330, 92).radius(8).fill({ color: '#ffffff', opacity: 0.88 }).stroke({ color: '#dddddd', width: 1 });
panelBg.back();

function sub(n) {
  return ['₀', '₁', '₂', '₃', '₄', '₅', '₆', '₇', '₈', '₉'][n] || String(n);
}

function add(a, b) { return { x: a.x + b.x, y: a.y + b.y }; }
function subPt(a, b) { return { x: a.x - b.x, y: a.y - b.y }; }
function mul(a, s) { return { x: a.x * s, y: a.y * s }; }
function dot(a, b) { return a.x * b.x + a.y * b.y; }
function len2(a) { return dot(a, a); }
function linePoint(p, d, t) { return add(p, mul(d, t)); }

function projectParam(p, d, x) {
  return dot(subPt(x, p), d) / Math.max(0.000001, len2(d));
}

function intersect(p, d, q, e) {
  var den = d.x * e.y - d.y * e.x;
  if (Math.abs(den) < 0.000001) return null;
  var qp = subPt(q, p);
  var t = (qp.x * e.y - qp.y * e.x) / den;
  var s = (qp.x * d.y - qp.y * d.x) / den;
  return { point: linePoint(p, d, t), t: t, s: s };
}

function segmentInfinite(p, d, pad) {
  pad = pad || 40;
  var xs = [-pad, W + pad], ys = [-pad, H + pad], hits = [];
  if (Math.abs(d.x) > 0.000001) {
    for (var i = 0; i < xs.length; i++) {
      var t = (xs[i] - p.x) / d.x;
      var y = p.y + t * d.y;
      if (y >= -pad - 1 && y <= H + pad + 1) hits.push({ x: xs[i], y: y });
    }
  }
  if (Math.abs(d.y) > 0.000001) {
    for (var j = 0; j < ys.length; j++) {
      var tt = (ys[j] - p.y) / d.y;
      var x = p.x + tt * d.x;
      if (x >= -pad - 1 && x <= W + pad + 1) hits.push({ x: x, y: ys[j] });
    }
  }
  if (hits.length < 2) return [linePoint(p, d, -10), linePoint(p, d, 10)];
  return [hits[0], hits[1]];
}

function rayEndpoint(o, d) {
  var best = null;
  var bounds = [
    { x: W + 60, vertical: true },
    { y: -60, vertical: false },
    { y: H + 60, vertical: false }
  ];
  for (var i = 0; i < bounds.length; i++) {
    var t, x, y;
    if (bounds[i].vertical) {
      if (Math.abs(d.x) < 0.000001) continue;
      t = (bounds[i].x - o.x) / d.x;
      x = bounds[i].x;
      y = o.y + t * d.y;
    } else {
      if (Math.abs(d.y) < 0.000001) continue;
      t = (bounds[i].y - o.y) / d.y;
      y = bounds[i].y;
      x = o.x + t * d.x;
    }
    if (t > 0 && x > -80 && x < W + 80 && y > -80 && y < H + 80) {
      if (!best || t < best.t) best = { x: x, y: y, t: t };
    }
  }
  return best || linePoint(o, d, 5);
}

function cr4(a1, a2, a3, a4) {
  var den1 = a2 - a3, den2 = a2 - a4, den3 = a1 - a4;
  if (Math.abs(den1 * den3) < 0.0000001) return NaN;
  return ((a1 - a3) / den1) / ((a1 - a4) / den2);
}

function crInfinityFirst(a2, a3, a4) {
  if (Math.abs(a2 - a3) < 0.0000001) return NaN;
  return (a2 - a4) / (a2 - a3);
}

function fmt(v) {
