var arrowMarker = draw.marker(18, 12, function (add) {
  add.path('M0,0 L18,6 L0,12 Z').fill(black);
});
arrowMarker.ref(16.5, 6).orient('auto');

var transLayer = draw.group();
var rayLayer = draw.group();
var guideLayer = draw.group();
var pointLayer = draw.group();
var labelLayer = draw.group();
var panelLayer = draw.group();

var pLine, qLine, rLine, infArrow, infLabel;
var formulaText, readP, readQ, readR, equalMark, panelBg;
var rays = [], pPts = [], qPts = [], rPts = [];
var pLabels = [], qLabels = [], rLabels = [];
var oPoint, oLabel;
var highlightRings = [];

function addLine(layer, color, width) {
  return layer.line(0, 0, 1, 1).stroke({ color: color, width: width, linecap: 'round' });
}

pLine = addLine(transLayer, magenta, 4.2);
qLine = addLine(transLayer, magenta, 4.2);
rLine = addLine(transLayer, magenta, 4.2);

for (var i = 0; i < 4; i++) rays[i] = addLine(rayLayer, black, 3.6);

infArrow = guideLayer.line(0, 0, 1, 1).stroke({ color: black, width: 3.1, linecap: 'round' });
infArrow.marker('end', arrowMarker);

function sub(n) {
  return ['₀', '₁', '₂', '₃', '₄', '₅', '₆', '₇', '₈', '₉'][n] || String(n);
}
function add(a, b) { return { x: a.x + b.x, y: a.y + b.y }; }
function subPt(a, b) { return { x: a.x - b.x, y: a.y - b.y }; }
function mul(a, s) { return { x: a.x * s, y: a.y * s }; }
function dot(a, b) { return a.x * b.x + a.y * b.y; }
function len2(a) { return dot(a, a); }
function linePoint(p, d, t) { return add(p, mul(d, t)); }

function projectParam(p, d, x) {
  return dot(subPt(x, p), d) / Math.max(0.000001, len2(d));
}

function intersect(p, d, q, e) {
  var den = d.x * e.y - d.y * e.x;
  if (Math.abs(den) < 0.000001) return null;
  var qp = subPt(q, p);
  var t = (qp.x * e.y - qp.y * e.x) / den;
  var s = (qp.x * d.y - qp.y * d.x) / den;
  return { point: linePoint(p, d, t), t: t, s: s };
}

function cr4(a1, a2, a3, a4) {
  var den1 = a2 - a3, den2 = a2 - a4, den3 = a1 - a4;
  if (Math.abs(den1 * den3) < 0.0000001) return NaN;
  return ((a1 - a3) / den1) / ((a1 - a4) / den2);
}

function crInfinityFirst(a2, a3, a4) {
  if (Math.abs(a2 - a3) < 0.0000001) return NaN;
  return (a2 - a4) / (a2 - a3);
}

function fmt(v) {
  return isFinite(v) ? v.toFixed(5) : 'undefined';
}

function makeLabel(txt, size) {
