    family: 'Times New Roman, Georgia, serif',
    size: size || 43,
    weight: '700'
  }).fill('#111').attr({
    'paint-order': 'stroke',
    stroke: '#fff',
    'stroke-width': 5,
    'stroke-linejoin': 'round'
