  qPts[j] = makePoint('Q', j);
  if (j > 0) rPts[j] = makePoint('R', j);
}

oPoint = pointLayer.circle(26).fill(black).center(state.O.x, state.O.y);
oPoint.css('cursor', 'pointer');
oPoint.on('mousemove', function (e) { showTooltip('O: drag the center of projection.', e); });
oPoint.on('mouseleave', function () { hideTooltip(); });
oPoint.on('click', function () {
  showPopup('Projection center O', 'All four correspondences are made by rays through this point. Moving O changes the apparent spacing of the projected points, but not the invariant cross-ratio.');
});
oPoint.on('pointerdown', function (e) {
  e.preventDefault();
  drag = { kind: 'O', idx: -1 };
  oPoint.node.setPointerCapture(e.pointerId);
});

for (var k = 0; k < 4; k++) {
  pLabels[k] = makeLabel('P' + sub(k + 1), 43);
  qLabels[k] = makeLabel('Q' + sub(k + 1), 43);
  if (k > 0) rLabels[k] = makeLabel('R' + sub(k + 1), 47);
}
oLabel = makeLabel('O', 48);
infLabel = makeLabel('R' + sub(1), 48);

panelBg = panelLayer.rect(395, 104).radius(8).fill({ color: '#ffffff', opacity: 0.90 }).stroke({ color: '#d8d8d8', width: 1 });
formulaText = panelLayer.text('CR(A₁,A₂,A₃,A₄) = (A₁A₃/A₂A₃) / (A₁A₄/A₂A₄)')
  .font({ family: 'Times New Roman, Georgia, serif', size: 19 })
  .fill('#111');
readP = panelLayer.text('').font({ family: 'sans-serif', size: 15 }).fill('#111');
readQ = panelLayer.text('').font({ family: 'sans-serif', size: 15 }).fill('#111');
readR = panelLayer.text('').font({ family: 'sans-serif', size: 15 }).fill('#111');
equalMark = panelLayer.text('equal within rounding').font({ family: 'sans-serif', size: 13, weight: '700' }).fill(magenta);

function segmentInfinite(p, d, pad) {
  pad = pad || 60;
  var candidates = [], xs = [-pad, W + pad], ys = [-pad, H + pad];
  for (var i = 0; i < xs.length; i++) {
    if (Math.abs(d.x) > 0.000001) {
      var t = (xs[i] - p.x) / d.x, y = p.y + t * d.y;
      if (y >= -pad && y <= H + pad) candidates.push({ x: xs[i], y: y, t: t });
    }
  }
  for (var j = 0; j < ys.length; j++) {
    if (Math.abs(d.y) > 0.000001) {
      var tt = (ys[j] - p.y) / d.y, x = p.x + tt * d.x;
      if (x >= -pad && x <= W + pad) candidates.push({ x: x, y: ys[j], t: tt });
    }
  }
  candidates.sort(function (a, b) { return a.t - b.t; });
  if (candidates.length < 2) return [linePoint(p, d, -10), linePoint(p, d, 10)];
  return [candidates[0], candidates[candidates.length - 1]];
}

function rayEndpoint(o, d) {
  var best = null;
  var tests = [
    { x: W + 45, vertical: true },
    { y: -45, vertical: false },
    { y: H + 45, vertical: false }
  ];
  for (var i = 0; i < tests.length; i++) {
    var t, x, y;
    if (tests[i].vertical) {
      if (Math.abs(d.x) < 0.000001) continue;
      t = (tests[i].x - o.x) / d.x;
      x = tests[i].x;
      y = o.y + t * d.y;
    } else {
      if (Math.abs(d.y) < 0.000001) continue;
      t = (tests[i].y - o.y) / d.y;
      y = tests[i].y;
      x = o.x + t * d.x;
    }
    if (t > 0 && x > -70 && x < W + 70 && y > -70 && y < H + 70) {
      if (!best || t < best.t) best = { x: x, y: y, t: t };
    }
  }
  return best || linePoint(o, d, 5);
}

function setLine(el, a, b) {
  el.plot(a.x, a.y, b.x, b.y);
}

function positionText(t, p, dx, dy) {
  t.move(p.x + dx, p.y + dy);
}

function screenPoint(evt) {
  var svg = draw.node;
  var pt = svg.createSVGPoint();
  pt.x = evt.clientX;
  pt.y = evt.clientY;
  var m = svg.getScreenCTM();
  if (!m) return { x: 0, y: 0 };
  return pt.matrixTransform(m.inverse());
}

function currentGeometry() {
  var P = [], Q = [], R = [], qT = [], rT = [];
  for (var i = 0; i < 4; i++) P[i] = linePoint(state.p0, state.pD, state.pT[i]);
  var dR = subPt(P[0], state.O);
  for (var j = 0; j < 4; j++) {
    var rd = subPt(P[j], state.O);
    var qi = intersect(state.O, rd, state.q0, state.qD);
    Q[j] = qi ? qi.point : { x: NaN, y: NaN };
    qT[j] = qi ? qi.s : NaN;
    if (j > 0) {
      var ri = intersect(state.O, rd, state.rAnchor, dR);
      R[j] = ri ? ri.point : { x: NaN, y: NaN };
      rT[j] = ri ? ri.s : NaN;
    }
  }
  return { P: P, Q: Q, R: R, qT: qT, rT: rT, dR: dR };
}

function clearHighlightRings() {
  for (var i = 0; i < highlightRings.length; i++) highlightRings[i].remove();
  highlightRings = [];
}

function ringAt(p, color) {
  if (!p || !isFinite(p.x) || !isFinite(p.y)) return;
  var r = guideLayer.circle(38).fill('none').stroke({ color: color, width: 2.6 }).center(p.x, p.y);
  highlightRings.push(r);
}

function updateFigure() {
  var g = currentGeometry();

  var ps = [linePoint(state.p0, state.pD, -0.14), linePoint(state.p0, state.pD, 1.18)];
  var qs = [linePoint(state.q0, state.qD, -0.12), linePoint(state.q0, state.qD, 1.12)];
  var rs = segmentInfinite(state.rAnchor, g.dR, 80);

  setLine(pLine, ps[0], ps[1]);
  setLine(qLine, qs[0], qs[1]);
  setLine(rLine, rs[0], rs[1]);

  for (var i = 0; i < 4; i++) {
    var end = rayEndpoint(state.O, subPt(g.P[i], state.O));
    setLine(rays[i], state.O, end);
    pPts[i].center(g.P[i].x, g.P[i].y);
    qPts[i].center(g.Q[i].x, g.Q[i].y);
    if (i > 0 && g.R[i]) rPts[i].center(g.R[i].x, g.R[i].y).show();
  }

  oPoint.center(state.O.x, state.O.y);

  positionText(oLabel, state.O, -60, -45);

  var po = [[14, 18], [13, 8], [12, 0], [-4, 18]];
  var qo = [[18, -4], [18, -2], [16, -5], [17, 0]];
  var ro = [null, [-28, -59], [-20, -58], [-26, -64]];

  for (var j = 0; j < 4; j++) {
    positionText(pLabels[j], g.P[j], po[j][0], po[j][1]);
    positionText(qLabels[j], g.Q[j], qo[j][0], qo[j][1]);
    if (j > 0 && g.R[j]) positionText(rLabels[j], g.R[j], ro[j][0], ro[j][1]);
  }

  var arrowY = state.rAnchor.y + ((1270 - state.rAnchor.x) / g.dR.x) * g.dR.y;
  arrowY = Math.max(70, Math.min(H - 55, arrowY));
  positionText(infLabel, { x: 1215, y: arrowY }, 0, -37);
  setLine(infArrow, { x: 1286, y: arrowY - 10 }, { x: 1360, y: arrowY - 10 });
  var infText = labelLayer.text('∞').font({ family: 'Times New Roman, Georgia, serif', size: 50, weight: '700' })
    .fill('#111').attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  if (infLabel._infText) infLabel._infText.remove();
  infLabel._infText = infText;
  infText.move(1370, arrowY - 48);

  var cP = cr4(state.pT[0], state.pT[1], state.pT[2], state.pT[3]);
  var cQ = cr4(g.qT[0], g.qT[1], g.qT[2], g.qT[3]);
  var cR = crInfinityFirst(g.rT[1], g.rT[2], g.rT[3]);

  panelBg.move(24, 24);
  formulaText.move(38, 35);
  readP.text('CR(P₁,P₂,P₃,P₄) = ' + fmt(cP)).move(38, 64);
  readQ.text('CR(Q₁,Q₂,Q₃,Q₄) = ' + fmt(cQ)).move(38, 84);
  readR.text('CR(R₁,R₂,R₃,R₄) = ' + fmt(cR)).move(38, 104);
  equalMark.move(250, 104);

  applyStepStyle(g);
}

function applyStepStyle(g) {
  clearHighlightRings();
  panelLayer.hide();

  for (var i = 0; i < 4; i++) rays[i].stroke({ color: black, width: 3.6 });
  pLine.stroke({ color: magenta, width: 4.2 });
  qLine.stroke({ color: magenta, width: 4.2 });
  rLine.stroke({ color: magenta, width: 4.2 });
  infArrow.stroke({ color: black, width: 3.1 });

  if (currentStep === 1) {
    panelLayer.show();
    for (var a = 0; a < 4; a++) {
      ringAt(g.P[a], magenta);
      ringAt(g.Q[a], magenta);
      if (a > 0) ringAt(g.R[a], magenta);
    }
  } else if (currentStep === 2) {
    panelLayer.show();
    ringAt(state.O, blue);
    for (var b = 0; b < 4; b++) rays[b].stroke({ color: blue, width: 4.0 });
  } else if (currentStep === 3) {
    panelLayer.show();
    rLine.stroke({ color: magenta, width: 5.0 });
    rays[0].stroke({ color: magenta, width: 4.2 });
    infArrow.stroke({ color: magenta, width: 3.6 });
  }

  transLayer.front();
  rayLayer.front();
  guideLayer.front();
  pointLayer.front();
  labelLayer.front();
  if (currentStep > 0) panelLayer.front();
}

document.addEventListener('pointermove', function (e) {
  if (!drag) return;
  var pt = screenPoint(e);

  if (drag.kind === 'O') {
    state.O.x = Math.max(30, Math.min(230, pt.x));
    state.O.y = Math.max(130, Math.min(560, pt.y));
  } else if (drag.kind === 'P') {
    state.pT[drag.idx] = projectParam(state.p0, state.pD, pt);
  } else if (drag.kind === 'Q') {
    var qOn = linePoint(state.q0, state.qD, projectParam(state.q0, state.qD, pt));
    var rayD = subPt(qOn, state.O);
    var hitP = intersect(state.O, rayD, state.p0, state.pD);
    if (hitP) state.pT[drag.idx] = hitP.s;
  } else if (drag.kind === 'R' && drag.idx > 0) {
    var geom = currentGeometry();
    var rOn = linePoint(state.rAnchor, geom.dR, projectParam(state.rAnchor, geom.dR, pt));
    var rRay = subPt(rOn, state.O);
    var hit = intersect(state.O, rRay, state.p0, state.pD);
    if (hit) state.pT[drag.idx] = hit.s;
  }
  updateFigure();
});

document.addEventListener('pointerup', function () { drag = null; });
document.addEventListener('pointercancel', function () { drag = null; });

pLine.on('mousemove', function (e) { showTooltip('P-line: the original four collinear points P₁–P₄.', e); })
  .on('mouseleave', function () { hideTooltip(); })
  .on('click', function () { showPopup('P-line', 'The four P points form one ordered collinear quadruple. Projection from O sends them to the Q-line and R-line while preserving their cross-ratio.'); });
qLine.on('mousemove', function (e) { showTooltip('Q-line: a projection of the same ordered quadruple.', e); })
  .on('mouseleave', function () { hideTooltip(); })
  .on('click', function () { showPopup('Q-line', 'The Q points are intersections of the same four rays with a different transversal. Their distances look different, but their cross-ratio matches the P points.'); });
rLine.on('mousemove', function (e) { showTooltip('R-line: parallel to the lowest projection ray, so R₁ is at infinity.', e); })
  .on('mouseleave', function () { hideTooltip(); })
  .on('click', function () { showPopup('R-line and infinity', 'Because the R-line is parallel to the ray through P₁ and Q₁, the corresponding point R₁ is not finite. The limiting cross-ratio formula still gives the same invariant value.'); });

var steps = [
  {
    title: 'Matched points on projection rays',
    narration: 'Each black ray from O links one corresponding triple of points, such as P3, Q3, and R3. The three magenta lines are different image lines of the same ordered four-point set.'
  },
  {
    title: 'Drag a finite point',
    narration: 'Drag one of the P, Q, or finite R points along its magenta line. The readout appears: the projected spacings change, but the cross-ratio values remain equal.'
  },
  {
    title: 'Move the center of projection',
    narration: 'Drag O to a new position. The four rays pivot and the projected points move, yet the common cross-ratio is unchanged.'
  },
  {
    title: 'Notice the point at infinity',
    narration: 'The R line is parallel to the lowest projection ray, so their intersection is represented by R1 at infinity. The same invariant survives this limiting case.'
  }
];

function setStep(n) {
  currentStep = Math.max(0, Math.min(steps.length - 1, n));
  document.getElementById('demoNarration').textContent = steps[currentStep].narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + ' / ' + steps.length;
  updateFigure();
}

function nextStep() { setStep(currentStep + 1); }
function prevStep() { setStep(currentStep - 1); }

window.nextStep = nextStep;
window.prevStep = prevStep;

setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The cross-ratio of four collinear points is preserved when those points are projected from any center onto other lines, even when one projected point lies at infinity.
KEY INSIGHT (what students should walk away understanding): Projection can dramatically change distances and even send a point to infinity, but it preserves the cross-ratio of four ordered collinear points.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
